import h5py
import json
import math
import sys

NON_TRAINABLE_SUBSTRINGS = ("moving_mean", "moving_variance")


def iter_datasets(h5, group_name="model_weights"):
    datasets = []

    def visit(name, obj):
        if isinstance(obj, h5py.Dataset):
            datasets.append((name, obj))

    root = h5[group_name]
    root.visititems(visit)
    return datasets


def count_trainable(path):
    total = 0
    non_trainable = 0
    counts = {}
    with h5py.File(path, "r") as h5:
        for name, ds in iter_datasets(h5):
            n = int(math.prod(ds.shape))
            key = name
            counts[key] = {"shape": list(ds.shape), "size": n}
            if any(sub in key for sub in NON_TRAINABLE_SUBSTRINGS):
                non_trainable += n
            else:
                total += n
    return total, non_trainable, counts


